# must not become process-wide ABI or interpose another SDK's implementation.
{
  global:
    ckfe_*;
    ckfea_*;
    ckfer_*;
    ckfet_*;
    ckfjr_*;
    ckfsp_*;
    ckfss_*;
  local:
    *;
};
